"""Assistant tab — renders HTML status page and triggers refresh commands.

Displays an HTML file from ~/source/personal-assistant/ and provides
a button to run a refresh command as a detached background process.
The process survives dashboard restarts; PID is tracked in a state file.
File-watch polling detects when the HTML is updated.
"""

from __future__ import annotations

import json
import logging
import os
import subprocess
import time
import tkinter as tk
from pathlib import Path
from typing import Any

from personal_assistant.models import ConsoleLogCallback, NotifyTabCallback
from personal_assistant.config import (
    ACTIONS_HTML,
    ASSISTANT_DIR,
    ASSISTANT_HTML,
    BG_OUTPUT,
    BG_WINDOW,
    COLOR_BUTTON,
    COLOR_BUTTON_ACTIVE,
    COLOR_HTML_FALLBACK_BG,
    COLOR_HTML_FALLBACK_FG,
    FG_DIM,
    FG_TEXT,
    FILE_WATCH_INTERVAL_MS,
    FONT_BODY,
    PAD,
    REFRESH_COMMAND,
)
from personal_assistant.state_repo import DEFAULT_STATE_PATH

logger = logging.getLogger(__name__)

# CSS injected into HTML frames for spacing
SPACING_CSS = (
    "body { line-height: 1.5; }"
    " h1, h2, h3, h4, h5 { margin-top: 1.2em; margin-bottom: 0.4em; }"
    " p { margin-top: 0.4em; margin-bottom: 0.4em; }"
    " ul, ol { margin-top: 0.4em; margin-bottom: 0.4em; }"
    " li { margin-bottom: 0.2em; }"
    " table { margin-bottom: 1em; }"
    " td, th { padding: 4px 8px; }"
)

PID_FILE = DEFAULT_STATE_PATH / "assistant_refresh.pid"


def _pid_alive(pid: int) -> bool:
    """Check if a process with the given PID is still running."""
    try:
        os.kill(pid, 0)
        return True
    except (OSError, ProcessLookupError):
        return False


def _pid_start_time(pid: int) -> float:
    """Get the start time of a process from /proc, or fall back to now."""
    try:
        stat = Path(f"/proc/{pid}/stat").read_text()
        # Field 22 (0-indexed: 21) is starttime in clock ticks since boot
        starttime_ticks = int(stat.split(")")[1].split()[19])
        clk_tck = os.sysconf("SC_CLK_TCK")
        # Boot time from /proc/stat
        for line in Path("/proc/stat").read_text().splitlines():
            if line.startswith("btime "):
                btime = int(line.split()[1])
                return btime + starttime_ticks / clk_tck
    except (OSError, ValueError, IndexError):
        pass
    return time.time()


def _format_age(seconds: int) -> str:
    """Format an age in seconds to a human-readable string."""
    if seconds < 60:
        return f"{seconds}s ago"
    elif seconds < 3600:
        return f"{seconds // 60}m ago"
    elif seconds < 86400:
        hours = seconds // 3600
        minutes = (seconds % 3600) // 60
        return f"{hours}h {minutes}m ago"
    else:
        return f"{seconds // 86400}d ago"


class AssistantTab:
    """Assistant tab for the PA dashboard.

    Renders an HTML page and provides a refresh button that launches
    a detached background process. PID is saved to a state file so the
    process can be tracked across dashboard restarts.
    """

    def __init__(
        self,
        parent: tk.Frame,
        root: tk.Tk,
        *,
        on_actions_refresh: Any = None,
        on_actions_status: Any = None,
        console_log: ConsoleLogCallback | None = None,
        notify_tab: NotifyTabCallback | None = None,
    ) -> None:
        self._parent = parent
        self._root = root
        self._on_actions_refresh = on_actions_refresh
        self._on_actions_status = on_actions_status
        self._console_log = console_log
        self._notify_tab = notify_tab
        self._running = False
        self._refresh_pid: int | None = None
        self._refresh_started: float = 0.0
        self._age_timer: str | None = None
        self._last_assistant_mtime: float = 0.0
        self._last_actions_mtime: float = 0.0
        self._build()
        self._recover_pid()
        self._start_age_timer()

    def _build(self) -> None:
        # Control bar
        controls = tk.Frame(self._parent, bg=BG_WINDOW)
        controls.pack(fill=tk.X, padx=PAD, pady=(PAD, 0))

        self._status_var = tk.StringVar(value="")
        tk.Label(
            controls,
            textvariable=self._status_var,
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=FONT_BODY,
        ).pack(side=tk.LEFT)

        self._refresh_btn = tk.Button(
            controls,
            text="Refresh",
            command=self._on_refresh,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=8,
        )
        self._refresh_btn.pack(side=tk.RIGHT)

        tk.Button(
            controls,
            text="\U0001f504",
            command=self._load_html,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=4,
        ).pack(side=tk.RIGHT, padx=(0, 4))

        # HTML display
        self._html_frame: Any = None
        self._build_html_frame()

    def _build_html_frame(self) -> None:
        """Build or rebuild the HTML display frame."""
        try:
            from tkinterweb import HtmlFrame

            if self._html_frame is not None:
                self._html_frame.destroy()

            import webbrowser

            self._html_frame = HtmlFrame(
                self._parent,
                messages_enabled=False,
                dark_theme_enabled=True,
                on_link_click=lambda url: webbrowser.open(url),
            )
            self._html_frame.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            self._load_html()
        except ImportError:
            # Fallback: plain text display
            fallback = tk.Text(
                self._parent,
                bg=BG_OUTPUT,
                fg=FG_TEXT,
                font=FONT_BODY,
                wrap=tk.WORD,
                state=tk.DISABLED,
                highlightthickness=0,
            )
            fallback.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            fallback.configure(state=tk.NORMAL)
            fallback.insert(
                "1.0",
                "tkinterweb not installed. Run: pip install tkinterweb[recommended]",
            )
            fallback.configure(state=tk.DISABLED)

    def _load_html(self) -> None:
        """Load the HTML file into the display."""
        if self._html_frame is None:
            return
        if ASSISTANT_HTML.exists():
            content = ASSISTANT_HTML.read_text(encoding="utf-8")
            self._html_frame.load_html(content)
            self._html_frame.add_css(SPACING_CSS)
        else:
            body = (
                f"<html><body style='background:{COLOR_HTML_FALLBACK_BG};"
                f"color:{COLOR_HTML_FALLBACK_FG};"
                "font-family:sans-serif;padding:20px'>"
                "<p>No status page found at:</p>"
                f"<code>{ASSISTANT_HTML}</code></body></html>"
            )
            self._html_frame.load_html(body)

    # --- PID management ---

    def _save_pid(self, pid: int) -> None:
        """Save the refresh process PID to a state file."""
        PID_FILE.parent.mkdir(parents=True, exist_ok=True)
        PID_FILE.write_text(json.dumps({"pid": pid}), encoding="utf-8")

    def _clear_pid(self) -> None:
        """Remove the PID state file."""
        self._refresh_pid = None
        try:
            PID_FILE.unlink(missing_ok=True)
        except OSError:
            pass

    def _recover_pid(self) -> None:
        """On startup, check for a previously running refresh process."""
        if not PID_FILE.exists():
            return
        try:
            data = json.loads(PID_FILE.read_text(encoding="utf-8"))
            pid = data.get("pid")
            if pid and _pid_alive(pid):
                self._refresh_pid = pid
                self._refresh_started = _pid_start_time(pid)
                self._running = True
                self._refresh_btn.configure(state="disabled", text=f"PID: {pid}")
                self._status_var.set("Refreshing...")
                self._log(
                    "[Assistant] recovered running refresh (PID %d)" % pid, "info"
                )
            else:
                self._clear_pid()
        except (json.JSONDecodeError, OSError, TypeError):
            self._clear_pid()

    # --- Timer ---

    def _start_age_timer(self) -> None:
        """Start updating the page age every 10 seconds."""
        self._update_age()

    def _update_age(self) -> None:
        """Update the status label with the age of the HTML file.

        Also detects file changes (auto-reload + bell) and monitors
        the refresh process PID.
        """
        # Monitor refresh process
        if self._running and self._refresh_pid is not None:
            if not _pid_alive(self._refresh_pid):
                # Process exited — check if it was success or failure
                # We can't get exit code from a detached process, so just
                # report completion. File-watch handles the HTML reload.
                self._log(
                    "[Assistant] refresh process exited (PID %d)" % self._refresh_pid,
                    "info",
                )
                self._clear_pid()
                self._running = False
                self._refresh_btn.configure(state="normal", text="Refresh")
            else:
                # Update elapsed time
                elapsed = int(time.time() - self._refresh_started)
                if elapsed < 60:
                    self._status_var.set(f"Refreshing... {elapsed}s")
                else:
                    self._status_var.set(
                        f"Refreshing... {elapsed // 60}m {elapsed % 60}s"
                    )

        # Check for assistant HTML changes
        if ASSISTANT_HTML.exists():
            mtime = ASSISTANT_HTML.stat().st_mtime
            if not self._running:
                age_seconds = int(time.time() - mtime)
                self._status_var.set(f"Updated {_format_age(age_seconds)}")

            if mtime != self._last_assistant_mtime:
                if self._last_assistant_mtime != 0.0:
                    self._load_html()
                    if self._notify_tab is not None:
                        self._notify_tab("Assistant")
                self._last_assistant_mtime = mtime
        else:
            if not self._running:
                self._status_var.set("No status page")

        # Check for actions HTML changes
        if ACTIONS_HTML.exists():
            actions_mtime = ACTIONS_HTML.stat().st_mtime
            if actions_mtime != self._last_actions_mtime:
                if self._last_actions_mtime != 0.0:
                    if self._on_actions_refresh is not None:
                        try:
                            self._on_actions_refresh()
                        except Exception:
                            pass
                    if self._notify_tab is not None:
                        self._notify_tab("Actions")
                self._last_actions_mtime = actions_mtime
            # Update Actions tab status
            if self._on_actions_status is not None:
                if self._running:
                    elapsed = int(time.time() - self._refresh_started)
                    if elapsed < 60:
                        self._on_actions_status(f"Refreshing... {elapsed}s")
                    else:
                        self._on_actions_status(
                            f"Refreshing... {elapsed // 60}m {elapsed % 60}s"
                        )
                else:
                    actions_age = int(time.time() - actions_mtime)
                    self._on_actions_status(f"Updated {_format_age(actions_age)}")
        elif self._on_actions_status is not None:
            if self._running:
                elapsed = int(time.time() - self._refresh_started)
                if elapsed < 60:
                    self._on_actions_status(f"Refreshing... {elapsed}s")
                else:
                    self._on_actions_status(
                        f"Refreshing... {elapsed // 60}m {elapsed % 60}s"
                    )
            else:
                self._on_actions_status("No actions page")

        self._age_timer = self._root.after(FILE_WATCH_INTERVAL_MS, self._update_age)

    # --- Refresh ---

    def _on_refresh(self) -> None:
        """Launch the refresh command as a detached background process."""
        if self._running:
            return
        self._running = True
        self._refresh_started = time.time()
        self._refresh_btn.configure(state="disabled")
        self._status_var.set("Refreshing...")

        # Git commit before refresh (quick, synchronous)
        self._git_commit()

        # Launch detached process
        try:
            proc = subprocess.Popen(
                REFRESH_COMMAND,
                cwd=str(ASSISTANT_DIR),
                shell=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                stdin=subprocess.DEVNULL,
                start_new_session=True,
            )
            self._refresh_pid = proc.pid
            self._save_pid(proc.pid)
            self._refresh_btn.configure(text=f"PID: {proc.pid}")
            self._log("[Assistant] refresh started (PID %d)" % proc.pid, "progress")
        except Exception as exc:
            logger.exception("Failed to launch refresh process")
            self._log(f"[Assistant] refresh launch failed: {exc}", "error")
            self._running = False
            self._refresh_btn.configure(state="normal", text="Refresh")

    def _git_commit(self) -> None:
        """Stage and commit changes in the assistant directory."""
        if not (ASSISTANT_DIR / ".git").is_dir():
            return
        try:
            subprocess.run(
                ["git", "add", "."],
                cwd=str(ASSISTANT_DIR),
                capture_output=True,
                timeout=10,
                check=False,
            )
            subprocess.run(
                ["git", "commit", "-m", "Auto-commit: assistant refresh"],
                cwd=str(ASSISTANT_DIR),
                capture_output=True,
                timeout=10,
                check=False,
            )
            subprocess.run(
                ["git", "push", "origin", "main"],
                cwd=str(ASSISTANT_DIR),
                capture_output=True,
                timeout=10,
                check=False,
            )
        except Exception as exc:
            logger.debug("Git commit in assistant dir failed: %s", exc)

    def _log(self, message: str, tag: str = "info") -> None:
        """Forward to dashboard console."""
        if self._console_log is not None:
            try:
                self._root.after(0, self._console_log, message, tag, "", "")
            except Exception:
                pass

    def on_destroy(self) -> None:
        """Called during dashboard shutdown to clean up resources."""
        if self._age_timer is not None:
            self._root.after_cancel(self._age_timer)
            self._age_timer = None
